// ServerInterface represents all server handlers.
type ServerInterface interface {
	// AdminListArticleCategories Article categories
	// (GET /v1/admin/article-categories)
	AdminListArticleCategories(w http.ResponseWriter, r *http.Request)
	// AdminCreateArticleCategory Add an article category. Roles, editor, admin
	// (POST /v1/admin/article-categories)
	AdminCreateArticleCategory(w http.ResponseWriter, r *http.Request)
	// AdminUpdateArticleCategory Rename or reorder an article category (the slug stays). Roles, editor, admin
	// (PUT /v1/admin/article-categories/{slug})
	AdminUpdateArticleCategory(w http.ResponseWriter, r *http.Request, slug string)
	// AdminListArticles Articles in any status, recently edited first (max 200)
	// (GET /v1/admin/articles)
	AdminListArticles(w http.ResponseWriter, r *http.Request, params AdminListArticlesParams)
	// AdminCreateArticle Create an article. Bodies are sanitized (ADR-0025). Roles, editor, admin
	// (POST /v1/admin/articles)
	AdminCreateArticle(w http.ResponseWriter, r *http.Request)
	// AdminGetArticle One article for editing
	// (GET /v1/admin/articles/{id})
	AdminGetArticle(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// AdminUpdateArticle Replace an article (archive = status archived). Roles, editor, admin
	// (PUT /v1/admin/articles/{id})
	AdminUpdateArticle(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// AdminListAuctions Metal auctions for editing, newest first
	// (GET /v1/admin/auctions)
	AdminListAuctions(w http.ResponseWriter, r *http.Request, params AdminListAuctionsParams)
	// AdminCreateAuction Add an auction. Roles, editor, admin
	// (POST /v1/admin/auctions)
	AdminCreateAuction(w http.ResponseWriter, r *http.Request)
	// AdminDeleteAuction Delete an auction and its PDF. Roles, editor, admin
	// (DELETE /v1/admin/auctions/{id})
	AdminDeleteAuction(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// AdminUpdateAuction Edit an auction, including its status. Roles, editor, admin
	// (PUT /v1/admin/auctions/{id})
	AdminUpdateAuction(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// AdminDeleteAuctionPdf Remove the auction's PDF notice. Roles, editor, admin
	// (DELETE /v1/admin/auctions/{id}/pdf)
	AdminDeleteAuctionPdf(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// AdminGetAuctionPdf The auction's PDF notice, for checking it
	// (GET /v1/admin/auctions/{id}/pdf)
	AdminGetAuctionPdf(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// AdminPutAuctionPdf Upload or replace the auction's PDF notice (a PDF, at most 10 MB). Roles, editor, admin
	// (PUT /v1/admin/auctions/{id}/pdf)
	AdminPutAuctionPdf(w http.ResponseWriter, r *http.Request, id openapi_types.UUID, params AdminPutAuctionPdfParams)
	// AdminCatalog Metals, products (active and inactive), categories and markets, for the catalog page
	// (GET /v1/admin/catalog)
	AdminCatalog(w http.ResponseWriter, r *http.Request)
	// AdminSetCatalogActive Deactivate or reactivate a product or a price series (nothing is deleted). Roles, editor, admin
	// (POST /v1/admin/catalog/active)
	AdminSetCatalogActive(w http.ResponseWriter, r *http.Request)
	// AdminListContactMessages Contact form messages, newest first (max 200)
	// (GET /v1/admin/contact-messages)
	AdminListContactMessages(w http.ResponseWriter, r *http.Request, params AdminListContactMessagesParams)
	// AdminUpdateContactMessage Mark a message handled / spam, with a note. Roles, support, admin
	// (PUT /v1/admin/contact-messages/{id})
	AdminUpdateContactMessage(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// AdminGetFaq Every FAQ category and item, published or not
	// (GET /v1/admin/faq)
	AdminGetFaq(w http.ResponseWriter, r *http.Request)
	// AdminCreateFaqCategory Add an FAQ category. Roles, editor, admin
	// (POST /v1/admin/faq/categories)
	AdminCreateFaqCategory(w http.ResponseWriter, r *http.Request)
	// AdminUpdateFaqCategory Rename or reorder an FAQ category. Roles, editor, admin
	// (PUT /v1/admin/faq/categories/{slug})
	AdminUpdateFaqCategory(w http.ResponseWriter, r *http.Request, slug string)
	// AdminCreateFaqItem Add a question. Its slug is the permanent deep link. Roles, editor, admin
	// (POST /v1/admin/faq/items)
	AdminCreateFaqItem(w http.ResponseWriter, r *http.Request)
	// AdminDeleteFaqItem Delete a question (prefer unpublishing). Roles, editor, admin
	// (DELETE /v1/admin/faq/items/{id})
	AdminDeleteFaqItem(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// AdminUpdateFaqItem Edit a question (the slug can't change, so shared links keep working). Roles, editor, admin
	// (PUT /v1/admin/faq/items/{id})
	AdminUpdateFaqItem(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// AdminListFlags The feature flags staff may switch (payments, English site, licences page)
	// (GET /v1/admin/flags)
	AdminListFlags(w http.ResponseWriter, r *http.Request)
	// AdminSetFlag Switch a feature flag on or off. Role, admin
	// (PUT /v1/admin/flags/{key})
	AdminSetFlag(w http.ResponseWriter, r *http.Request, key string)
	// AdminCreateMetal Add a metal. Roles, editor, admin
	// (POST /v1/admin/metals)
	AdminCreateMetal(w http.ResponseWriter, r *http.Request)
	// AdminListNotifications The latest 200 SMS sent or tried (reminders, price SMS), newest first
	// (GET /v1/admin/notifications)
	AdminListNotifications(w http.ResponseWriter, r *http.Request, params AdminListNotificationsParams)
	// AdminListOrders Latest orders (max 100), optionally filtered
	// (GET /v1/admin/orders)
	AdminListOrders(w http.ResponseWriter, r *http.Request, params AdminListOrdersParams)
	// AdminListPages Static pages
	// (GET /v1/admin/pages)
	AdminListPages(w http.ResponseWriter, r *http.Request)
	// AdminGetPage One page for editing
	// (GET /v1/admin/pages/{slug})
	AdminGetPage(w http.ResponseWriter, r *http.Request, slug string)
	// AdminUpdatePage Save a page. `version` must be the one you loaded (409 CONFLICT if someone saved in between). Roles, editor, admin
	// (PUT /v1/admin/pages/{slug})
	AdminUpdatePage(w http.ResponseWriter, r *http.Request, slug string)
	// AdminCreatePrice Manual price entry (fallback when a source is down, SCOPE §13)
	// (POST /v1/admin/prices)
	AdminCreatePrice(w http.ResponseWriter, r *http.Request)
	// AdminPricesAt The price of every series at a moment (its last published point at or before it), for entering history
	// (GET /v1/admin/prices/at)
	AdminPricesAt(w http.ResponseWriter, r *http.Request, params AdminPricesAtParams)
	// AdminBulkPrices Bulk manual entry (the admin parses the CSV). Run with dryRun first to show the diff
	// (POST /v1/admin/prices/bulk)
	AdminBulkPrices(w http.ResponseWriter, r *http.Request)
	// AdminListQuarantine Points held back by the outlier gate, oldest first
	// (GET /v1/admin/prices/quarantine)
	AdminListQuarantine(w http.ResponseWriter, r *http.Request)
	// AdminReviewPrice Approve (publish) or reject a quarantined point. Roles, editor, admin
	// (POST /v1/admin/prices/{id}/review)
	AdminReviewPrice(w http.ResponseWriter, r *http.Request, id string)
	// AdminVoidPrice Void a published point (a wrong entry). It is kept as rejected, never deleted. Roles, editor, admin
	// (POST /v1/admin/prices/{id}/void)
	AdminVoidPrice(w http.ResponseWriter, r *http.Request, id string)
	// AdminCreateProduct Add a product of a metal. Roles, editor, admin
	// (POST /v1/admin/products)
	AdminCreateProduct(w http.ResponseWriter, r *http.Request)
	// AdminDecideRefund Approve (order refunded, plan cancelled) or reject a refund request. Role, admin
	// (POST /v1/admin/refunds/{id}/decision)
	AdminDecideRefund(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// AdminListSeries Every series with its latest price and outlier threshold
	// (GET /v1/admin/series)
	AdminListSeries(w http.ResponseWriter, r *http.Request)
	// AdminCreateSeries Add a price series (product × market × currency × unit). Roles, editor, admin
	// (POST /v1/admin/series)
	AdminCreateSeries(w http.ResponseWriter, r *http.Request)
	// AdminSeriesPoints Recent points of one series, newest first, with who entered or voided each (price history)
	// (GET /v1/admin/series/{slug}/points)
	AdminSeriesPoints(w http.ResponseWriter, r *http.Request, slug string, params AdminSeriesPointsParams)
	// AdminGetSettings Editable site settings (contact details, social links)
	// (GET /v1/admin/settings)
	AdminGetSettings(w http.ResponseWriter, r *http.Request)
	// AdminUpdateSettings Save site settings. Role, admin
	// (PUT /v1/admin/settings)
	AdminUpdateSettings(w http.ResponseWriter, r *http.Request)
	// AdminListSources Source health (last run, last success, stale flag)
	// (GET /v1/admin/sources)
	AdminListSources(w http.ResponseWriter, r *http.Request)
	// AdminListSubscriptions Latest subscriptions (optionally for one user)
	// (GET /v1/admin/subscriptions)
	AdminListSubscriptions(w http.ResponseWriter, r *http.Request, params AdminListSubscriptionsParams)
	// AdminGrantSubscription Grant a subscription manually (until checkout exists). Role, admin
	// (POST /v1/admin/subscriptions)
	AdminGrantSubscription(w http.ResponseWriter, r *http.Request)
	// AdminSupportSummary Counts for the admin menu badges
	// (GET /v1/admin/support/summary)
	AdminSupportSummary(w http.ResponseWriter, r *http.Request)
	// AdminListTickets The support queue (open first, high priority first, oldest waiting first)
	// (GET /v1/admin/tickets)
	AdminListTickets(w http.ResponseWriter, r *http.Request, params AdminListTicketsParams)
	// AdminGetTicket A ticket with its messages
	// (GET /v1/admin/tickets/{id})
	AdminGetTicket(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// AdminReplyTicket Reply as support (the ticket becomes "answered"). Roles, support, admin
	// (POST /v1/admin/tickets/{id}/messages)
	AdminReplyTicket(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// AdminSetTicketStatus Change a ticket's status. Roles, support, admin
	// (PUT /v1/admin/tickets/{id}/status)
	AdminSetTicketStatus(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// AdminListUsers Search users by mobile, name or id (max 50)
	// (GET /v1/admin/users)
	AdminListUsers(w http.ResponseWriter, r *http.Request, params AdminListUsersParams)
	// AdminVisits Daily visitor stats (last 30 days) and the signed-in visitors of one day (default today, Tehran)
	// (GET /v1/admin/visits)
	AdminVisits(w http.ResponseWriter, r *http.Request, params AdminVisitsParams)
	// ListArticleCategories Topic tabs of the analysis page (besides metals)
	// (GET /v1/article-categories)
	ListArticleCategories(w http.ResponseWriter, r *http.Request, params ListArticleCategoriesParams)
	// ListArticles Published articles, newest first. Bodies are never listed
	// (GET /v1/articles)
	ListArticles(w http.ResponseWriter, r *http.Request, params ListArticlesParams)
	// GetArticle One published article. `body` is present only when the caller's plan includes its type
	// (GET /v1/articles/{slug})
	GetArticle(w http.ResponseWriter, r *http.Request, slug string, params GetArticleParams)
	// ListAuctions Metal auctions, newest first. The deadline, place, organiser, details and PDF need auctions.read (Gold)
	// (GET /v1/auctions)
	ListAuctions(w http.ResponseWriter, r *http.Request, params ListAuctionsParams)
	// GetAuctionPdf An auction's PDF notice. Needs auctions.read (Gold) → 403 FEATURE_LOCKED; anonymous → 401
	// (GET /v1/auctions/{id}/pdf)
	GetAuctionPdf(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// EstimateLoad Estimate a load's value (SCOPE §8). Needs calculator.use (Gold) → 403 FEATURE_LOCKED
	// (POST /v1/calculator/estimate)
	EstimateLoad(w http.ResponseWriter, r *http.Request)
	// ListCategories List product categories (raw materials, intermediate products, scrap)
	// (GET /v1/categories)
	ListCategories(w http.ResponseWriter, r *http.Request, params ListCategoriesParams)
	// StartCheckout Create an order and start its payment. Returns the gateway URL to send the browser to
	// (POST /v1/checkout)
	StartCheckout(w http.ResponseWriter, r *http.Request, params StartCheckoutParams)
	// QuoteCheckout Price a purchase for the user (credit for an upgrade, start date for a renewal) without creating anything
	// (POST /v1/checkout/quote)
	QuoteCheckout(w http.ResponseWriter, r *http.Request)
	// SendContactMessage Contact form (anonymous allowed; rate-limited per IP → 429 RATE_LIMITED)
	// (POST /v1/contact)
	SendContactMessage(w http.ResponseWriter, r *http.Request)
	// GetFaq Published FAQ by category (the page, its search and its FAQPage schema use exactly this)
	// (GET /v1/faq)
	GetFaq(w http.ResponseWriter, r *http.Request, params GetFaqParams)
	// ListMarkets List markets / price sources
	// (GET /v1/markets)
	ListMarkets(w http.ResponseWriter, r *http.Request, params ListMarketsParams)
	// GetMe The signed-in user's profile and current plan (refreshes the local profile from the token)
	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// ListMyAlerts The caller's SMS price alerts (listed even after the plan lapses, so they can be removed)
	// (GET /v1/me/alerts)
	ListMyAlerts(w http.ResponseWriter, r *http.Request, params ListMyAlertsParams)
	// CreateMyAlert Add an SMS price alert. Needs alerts.sms (Gold) → 403 FEATURE_LOCKED; 409 CONFLICT at the maximum
	// (POST /v1/me/alerts)
	CreateMyAlert(w http.ResponseWriter, r *http.Request, params CreateMyAlertParams)
	// DeleteMyAlert Delete an alert
	// (DELETE /v1/me/alerts/{id})
	DeleteMyAlert(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// SetMyAlertActive Pause or resume an alert (resuming needs Gold and re-arms it)
	// (PUT /v1/me/alerts/{id})
	SetMyAlertActive(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// ListMyCalculations Saved calculations (newest first, max 50)
	// (GET /v1/me/calculations)
	ListMyCalculations(w http.ResponseWriter, r *http.Request)
	// SaveMyCalculation Compute and save a calculation (Gold). 409 CONFLICT at 50 saved
	// (POST /v1/me/calculations)
	SaveMyCalculation(w http.ResponseWriter, r *http.Request)
	// DeleteMyCalculation Delete a saved calculation
	// (DELETE /v1/me/calculations/{id})
	DeleteMyCalculation(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// GetEntitlements Evaluated feature map for the caller (anonymous = free)
	// (GET /v1/me/entitlements)
	GetEntitlements(w http.ResponseWriter, r *http.Request)
	// ListMyOrders The user's orders (billing history), newest first
	// (GET /v1/me/orders)
	ListMyOrders(w http.ResponseWriter, r *http.Request)
	// GetMyOrder One of the user's orders (payment result page)
	// (GET /v1/me/orders/{id})
	GetMyOrder(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// RequestRefund Ask for a refund (within 7 days of payment, if no paid feature was used)
	// (POST /v1/me/orders/{id}/refund)
	RequestRefund(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// GetMySmsSettings The user's main metal for price SMS and whether they're on (sent to Gold only)
	// (GET /v1/me/sms-settings)
	GetMySmsSettings(w http.ResponseWriter, r *http.Request)
	// SetMySmsSettings Choose the main metal and turn price SMS on or off. Needs alerts.sms (Gold) → 403 FEATURE_LOCKED
	// (PUT /v1/me/sms-settings)
	SetMySmsSettings(w http.ResponseWriter, r *http.Request)
	// ListMySubscriptions The user's subscriptions, newest first (includes queued ones)
	// (GET /v1/me/subscriptions)
	ListMySubscriptions(w http.ResponseWriter, r *http.Request)
	// ListMyTickets The caller's tickets, latest activity first
	// (GET /v1/me/tickets)
	ListMyTickets(w http.ResponseWriter, r *http.Request)
	// CreateTicket Open a ticket with its first message. The same Idempotency-Key returns the first ticket (200)
	// (POST /v1/me/tickets)
	CreateTicket(w http.ResponseWriter, r *http.Request, params CreateTicketParams)
	// GetMyTicket One of the caller's tickets with its messages
	// (GET /v1/me/tickets/{id})
	GetMyTicket(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// CloseMyTicket Close one of the caller's tickets
	// (POST /v1/me/tickets/{id}/close)
	CloseMyTicket(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// ReplyMyTicket Reply to one of the caller's tickets (reopens it if closed)
	// (POST /v1/me/tickets/{id}/messages)
	ReplyMyTicket(w http.ResponseWriter, r *http.Request, id openapi_types.UUID)
	// ListMetals List base metals
	// (GET /v1/metals)
	ListMetals(w http.ResponseWriter, r *http.Request, params ListMetalsParams)
	// GetPage A static page (about, terms, privacy, licenses). 404 when unpublished
	// (GET /v1/pages/{slug})
	GetPage(w http.ResponseWriter, r *http.Request, slug string, params GetPageParams)
	// VerifyPayment Complete a payment after the gateway redirected the browser back (called by the website's callback page)
	// (POST /v1/payments/verify)
	VerifyPayment(w http.ResponseWriter, r *http.Request)
	// ListPlans List active subscription plans with current prices
	// (GET /v1/plans)
	ListPlans(w http.ResponseWriter, r *http.Request, params ListPlansParams)
	// ListPrices Latest price per series
	// (GET /v1/prices)
	ListPrices(w http.ResponseWriter, r *http.Request, params ListPricesParams)
	// ListSeriesPoints Price history of one series, downsampled to at most ~300 points
	// (GET /v1/series/{slug}/points)
	ListSeriesPoints(w http.ResponseWriter, r *http.Request, slug string, params ListSeriesPointsParams)
	// GetSite Public site settings (contact details, social links, which optional pages are on)
	// (GET /v1/site)
	GetSite(w http.ResponseWriter, r *http.Request, params GetSiteParams)
	// RecordVisit Count a page view for the daily visitor stats (sent by the website; cookieless, robots ignored)
	// (POST /v1/visits)
	RecordVisit(w http.ResponseWriter, r *http.Request)
}

